from fractions import Fraction

def show(a, b):
    # a + bi as text
    if b < 0:
        return f"{a} - {-b}i"
    return f"{a} + {b}i"

def multiply(a, b, c, d):
    # (a + bi)(c + di) as its two parts
    return a * c - b * d, a * d + b * c

def divide(a, b, c, d):
    # (a + bi) / (c + di) as its two parts, exact Fractions
    bottom = c * c + d * d
    return Fraction(a * c + b * d, bottom), Fraction(b * c - a * d, bottom)

count = int(input())
for k in range(count):
    op = input()
    a = int(input())
    b = int(input())
    c = int(input())
    d = int(input())
    if op == "*":
        p, q = multiply(a, b, c, d)
    else:
        p, q = divide(a, b, c, d)
    print(f"({show(a, b)}) {op} ({show(c, d)}) = {show(p, q)}")
